#!/usr/bin/env python3
"""Generate V3's twelve draft pairs, independently of V2's eight-card selection."""
import argparse
import json
from pathlib import Path
from build_v2_content import render as render_selected

ROOT = Path(__file__).resolve().parents[1]
IDS = ('tg-002', 'tg-001', 'tg-004', 'tg-003', 'tg-011', 'tg-028',
       'tg-031', 'tg-036', 'tg-010', 'tg-012', 'tg-014', 'tg-026')


def render(data):
    return render_selected(data, ids=IDS).replace(
        '// Generated by tools/build_v2_content.py.',
        '// Generated by tools/build_v3_content.py.', 1)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    output = render(json.loads((ROOT / 'content/cards.json').read_text()))
    path = ROOT / 'trailguide_v3/cards_generated.h'
    if args.check:
        if not path.exists() or path.read_text() != output:
            parser.exit(1, 'V3 generated content is stale\n')
        print('V3 draft content is current (twelve pairs).')
    else:
        path.write_text(output)
        print('Generated twelve draft V3 pairs.')


if __name__ == '__main__':
    main()
